BEGIN;
CREATE TABLE hr_employment_contracts(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,contract_type TEXT NOT NULL CHECK(contract_type IN('INDEFINITE','FIXED_TERM','PART_TIME','PROJECT','CONTRACTOR')),starts_on DATE NOT NULL,ends_on DATE,renewal_notice_days INTEGER NOT NULL DEFAULT 30,status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('DRAFT','ACTIVE','EXPIRED','TERMINATED','RENEWED')),document_id TEXT REFERENCES hr_personnel_documents(id) ON DELETE SET NULL,terms JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(ends_on IS NULL OR ends_on>=starts_on));
CREATE INDEX hr_employment_contracts_expiry_idx ON hr_employment_contracts(tenant_id,company_id,status,ends_on);
CREATE TABLE hr_business_travel(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,purpose TEXT NOT NULL,destination TEXT NOT NULL,starts_on DATE NOT NULL,ends_on DATE NOT NULL,advance_amount DECIMAL(14,2) NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'TRY',status TEXT NOT NULL DEFAULT 'REQUESTED' CHECK(status IN('REQUESTED','APPROVED','IN_PROGRESS','COMPLETED','SETTLED','REJECTED','CANCELLED')),advance_id TEXT REFERENCES hr_employee_advances(id) ON DELETE SET NULL,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(ends_on>=starts_on));
CREATE INDEX hr_business_travel_staff_idx ON hr_business_travel(tenant_id,staff_id,starts_on DESC);
CREATE TABLE hr_surveys(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name TEXT NOT NULL,survey_type TEXT NOT NULL CHECK(survey_type IN('ENGAGEMENT','PULSE','ENPS','EXIT','CUSTOM')),anonymous BOOLEAN NOT NULL DEFAULT FALSE,starts_at TIMESTAMP(3),ends_at TIMESTAMP(3),status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','OPEN','CLOSED')),questions JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hr_survey_responses(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,survey_id TEXT NOT NULL REFERENCES hr_surveys(id) ON DELETE CASCADE,staff_id TEXT REFERENCES staff(id) ON DELETE SET NULL,answers JSONB NOT NULL DEFAULT '{}'::jsonb,submitted_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(survey_id,staff_id));
CREATE TABLE hr_headcount_plans(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT REFERENCES branches(id) ON DELETE CASCADE,department_id TEXT REFERENCES hr_departments(id) ON DELETE CASCADE,team_id TEXT REFERENCES hr_teams(id) ON DELETE CASCADE,position_id TEXT REFERENCES hr_positions(id) ON DELETE CASCADE,period_month DATE NOT NULL,target_headcount INTEGER NOT NULL CHECK(target_headcount>=0),planned_hires INTEGER NOT NULL DEFAULT 0,planned_exits INTEGER NOT NULL DEFAULT 0,notes TEXT,UNIQUE(tenant_id,company_id,branch_id,department_id,team_id,position_id,period_month));
CREATE INDEX hr_headcount_plans_period_idx ON hr_headcount_plans(tenant_id,company_id,period_month);
CREATE TABLE hr_workforce_scenarios(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name TEXT NOT NULL,scenario_type TEXT NOT NULL,assumptions JSONB NOT NULL DEFAULT '{}'::jsonb,starts_on DATE NOT NULL,horizon_months INTEGER NOT NULL CHECK(horizon_months BETWEEN 1 AND 36),status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','ACTIVE','ARCHIVED')),created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hr_workforce_scenario_results(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,scenario_id TEXT NOT NULL REFERENCES hr_workforce_scenarios(id) ON DELETE CASCADE,period_month DATE NOT NULL,branch_id TEXT REFERENCES branches(id) ON DELETE CASCADE,required_fte DECIMAL(10,2),payroll_impact DECIMAL(16,2),utilization_impact DECIMAL(8,4),profitability_impact DECIMAL(16,2),details JSONB NOT NULL DEFAULT '{}'::jsonb,UNIQUE(scenario_id,period_month,branch_id));
COMMIT;
